class Solution {
public:
    vector<int> findClosestElements(vector<int>& arr, int k, int x) {
        int n=arr.size();
        int low=0,high=n-1;
        while(high-low>=k)
        {
            if(x-arr[low]<=arr[high]-x)
                high--;
            else
                low++;
        }
        return vector<int>(arr.begin()+low,arr.begin()+high+1);
    }
};
